"""cam_studio.cam.chipload — Расчет режимов резания, нагрузки на зуб и рисков прижога древесины."""

import math

# Твердость по шкале Янки (Janka Hardness, lbf)
WOOD_HARDNESS = {
    'walnut': 1010,   # Американский орех
    'maple': 1450,    # Сахарный клен
    'oak': 1290,      # Белый дуб
    'ash': 1320,      # Ясень
    'cherry': 950,    # Вишня
    'pine': 420,      # Сосна
    'birch': 1260,    # Береза
    'beech': 1300     # Бук
}

# Положения диска Makita RT0701C (1..6)
MAKITA_DISC = [
    (1, 10000),
    (2, 12000),
    (3, 17000),
    (4, 22000),
    (5, 27000),
    (6, 30000)
]


def calculate_feeds_speeds(tool_dia_mm: float, flutes: int, material: str, target_rpm: int = 18000, cut_depth_mm: float = 5.0) -> dict:
    """
    Расчет скорости подачи, скорости резания, чип-лоада и рисков прижога.
    
    c_z (chip load) = F / (RPM * flutes)
    F (подача, мм/мин) = RPM * flutes * c_z
    V_c (скорость резания, м/мин) = pi * D * RPM / 1000
    """
    mat_key = material.lower().strip()
    hardness = WOOD_HARDNESS.get(mat_key, 1100)

    # Оптимальная толщина стружки для деревообрабатывающих концевых фрез (6.35мм)
    scale = math.sqrt(tool_dia_mm / 6.35)
    if hardness >= 1300:
        c_z_opt = 0.07 * scale
    elif hardness >= 900:
        c_z_opt = 0.09 * scale
    else:
        c_z_opt = 0.14 * scale

    # Расчет рабочей подачи
    feed_mm_min = target_rpm * flutes * c_z_opt
    
    # Линейная скорость резания
    cutting_speed_m_min = (math.pi * tool_dia_mm * target_rpm) / 1000.0

    # Оценка рисков:
    # 1. Прижог (burn_risk): если фреза трет дерево вместо резания
    burn_risk = c_z_opt < 0.035 or (target_rpm > 24000 and feed_mm_min < 1500)
    
    # 2. Перегруз инструмента (overload_risk)
    overload_risk = c_z_opt > (0.18 * scale) or (cut_depth_mm > tool_dia_mm * 1.5)

    # Рекомендация диска Makita RT0701C
    disc = 3
    for d, rpm in MAKITA_DISC:
        if target_rpm <= rpm:
            disc = d
            break

    return {
        'material': material,
        'janka_hardness': hardness,
        'chip_load_mm_tooth': round(c_z_opt, 4),
        'feed_mm_min': round(feed_mm_min, 1),
        'cutting_speed_m_min': round(cutting_speed_m_min, 1),
        'rpm': target_rpm,
        'burn_risk': burn_risk,
        'overload_risk': overload_risk,
        'makita_dial': disc,
        'advice': "Обороты и подача сбалансированы" if not (burn_risk or overload_risk) else (
            "ВНИМАНИЕ: Слишком высокая частота вращения при низкой подаче — риск прижога древесины!" if burn_risk
            else "ВНИМАНИЕ: Слишком большая нагрузка на зуб — снизьте глубину или подачу!"
        )
    }
